-- Database security and performance regression tests.
begin;
create extension if not exists pgtap;
select plan(36);
select ok(has_function_privilege('anon', 'public.increment_location_view(uuid)', 'execute'), 'anonymous users can execute the atomic view RPC');
select ok(not has_function_privilege('public', 'public.increment_location_view(uuid)', 'execute'), 'public role cannot execute the view RPC');
select ok(has_function_privilege('authenticated', 'public.approve_location_claim(uuid)', 'execute'), 'authenticated users can execute claim approval RPC');
select ok(not has_function_privilege('anon', 'public.approve_location_claim(uuid)', 'execute'), 'anonymous users cannot execute claim approval RPC');
select ok(has_function_privilege('anon', 'public.current_app_role()', 'execute'), 'role helper is callable by anon for public RLS');
select ok(has_function_privilege('authenticated', 'public.is_admin_or_moderator()', 'execute'), 'moderation helper is callable by authenticated users');
select ok(to_regprocedure('public.protect_location_system_fields()') is not null, 'location trigger protection function exists');
select ok(to_regprocedure('public.protect_profile_role()') is not null, 'profile role protection function exists');
select ok(not has_function_privilege('anon', 'public.protect_location_system_fields()', 'execute'), 'location trigger function is not callable by anon');
select ok(not has_function_privilege('authenticated', 'public.refresh_location_rating()', 'execute'), 'rating trigger function is not callable by authenticated users');
select ok(strpos(lower(pg_get_functiondef('public.approve_location_claim(uuid)'::regprocedure)), 'for update') > 0, 'claim approval locks rows during validation');
select ok(strpos(lower(pg_get_functiondef('public.approve_location_claim(uuid)'::regprocedure)), 'location is no longer available for claim approval') > 0, 'claim approval rejects stale location state');
select ok(strpos(lower(pg_get_functiondef('public.approve_location_claim(uuid)'::regprocedure)), 'role = ''owner''::public.app_role') > 0, 'approved claim promotes a normal claimant to owner');
select ok(exists (select 1 from pg_enum e join pg_type t on t.oid=e.enumtypid where t.typname='app_role' and e.enumlabel='owner'), 'owner role exists in the app_role enum');
select col_not_null('public', 'locations', 'timezone', 'locations have a timezone for live opening status');
select col_is_fk('public', 'location_closures', 'location_id', 'closures belong to a location');
select ok(to_regclass('public.location_closures_location_dates_idx') is not null, 'closure date index exists');
select ok(to_regprocedure('public.protect_location_closure_identity()') is not null, 'closure identity protection function exists');
select ok((select pg_get_constraintdef(oid) like '%closure_type = ''definitive''%' from pg_constraint where conrelid = 'public.location_closures'::regclass and conname = 'location_closures_dates_check'), 'definitive closures cannot have an end date');
select col_is_pk('public', 'locations', 'id', 'locations has a primary key');
select col_not_null('public', 'locations', 'view_count', 'view_count remains non-null');
select col_not_null('public', 'locations', 'favorite_count', 'favorite_count remains non-null');
select col_not_null('public', 'locations', 'review_count', 'review_count remains non-null');
select ok(to_regclass('public.locations_public_category_created_idx') is not null, 'directory category/status index exists');
select ok(to_regclass('public.locations_name_trgm_idx') is not null, 'name substring index exists');
select ok(to_regclass('public.locations_city_trgm_idx') is not null, 'city substring index exists');
select ok(to_regclass('public.locations_description_trgm_idx') is not null, 'description substring index exists');
select ok(to_regclass('public.ownership_transfers') is not null, 'ownership transfer table exists');
select ok(to_regclass('public.ownership_transfers_one_pending_per_location_idx') is not null, 'only one pending transfer per location is enforced');
select ok(has_table_privilege('authenticated', 'public.ownership_transfers', 'select'), 'authenticated users can read transfer rows through RLS');
select ok(not has_function_privilege('anon', 'public.request_ownership_transfer(uuid,text,text)', 'execute'), 'anonymous users cannot request transfers');
select ok(has_function_privilege('authenticated', 'public.request_ownership_transfer(uuid,text,text)', 'execute'), 'authenticated users can request transfers');
select ok(has_function_privilege('authenticated', 'public.accept_ownership_transfer(uuid)', 'execute'), 'authenticated users can accept transfers');
select ok(strpos(lower(pg_get_functiondef('public.request_ownership_transfer(uuid,text,text)'::regprocedure)), 'auth.users') > 0, 'transfer request resolves the recipient server-side');
select ok(strpos(lower(pg_get_functiondef('public.accept_ownership_transfer(uuid)'::regprocedure)), 'for update') > 0, 'transfer acceptance locks the transfer and location');
select ok(strpos(lower(pg_get_functiondef('public.accept_ownership_transfer(uuid)'::regprocedure)), 'location is no longer transferable') > 0, 'transfer acceptance rejects stale ownership state');
select * from finish();
rollback;
